static void service(collector_t *c, int retry_rank)
{
    for (int r = 0; r < HOSTS; r++) {
        uint32_t eligible = eligible_prefix(c, r);
        if (eligible == 0) {
            continue;
        }
        if (!(eligible > c->U[r] || c->repeat[r])) {
            continue;
        }
        if (!send_upstream_ack(c, r, eligible)) {
            return;
        }
        if (eligible > c->U[r]) {
            c->U[r] = eligible;
        }
        c->repeat[r] = 0;
    }

    if (retry_rank >= 0) {
        int d = retry_rank;
        uint32_t q = c->A[d];
        while (q < c->S[d]) {
            if (!send_result(c, d, q)) {
                return;
            }
            q++;
        }
    }

    for (int d = 0; d < HOSTS; d++) {
        if (!is_destination(c, d)) {
            continue;
        }
        uint32_t total = dest_total(c, d);
        while (c->S[d] < total) {
            uint32_t q = c->S[d];
            if (!result_ready(c, d, q)) {
                break;
            }
            if (!send_result(c, d, q)) {
                return;
            }
            c->S[d]++;
        }
    }
}
